// Parse admin command
const command = $json.body?.command || $json.command || '';
const args = $json.body?.args || $json.args || [];
const userId = $json.body?.userId || $json.userId || '';

let action = 'list'; // default
let target = '';

if (args.length > 0) {
  action = args[0].toLowerCase(); // allow, revoke, list
  if (args.length > 1) {
    target = args[1]; // channel name or ID
  }
}

return {
  json: {
    command,
    action,
    target,
    userId,
    timestamp: new Date().toISOString()
  }
};

// Verify user is admin
const userId = $node['Parse Command'].json.userId;
const whitelistData = JSON.parse($node['Load Whitelist'].json.data);

const isAdmin = whitelistData.admins.some(admin => 
  admin.id === userId || admin.aadObjectId === userId
);

return {
  json: {
    isAdmin,
    whitelistData,
    commandData: $node['Parse Command'].json
  }
};

// Unauthorized response
const templates = JSON.parse($node['Load Templates'].json.data);

return {
  json: {
    responseText: templates.errors.unauthorized_admin
  }
};

// Add channel to whitelist
const whitelist = $node['Verify Admin'].json.whitelistData;
const target = $node['Verify Admin'].json.commandData.target;
const userId = $node['Verify Admin'].json.commandData.userId;
const timestamp = $node['Verify Admin'].json.commandData.timestamp;

if (!target) {
  return {
    json: {
      success: false,
      responseText: 'Please specify a channel. Usage: /admin allow #channel-name'
    }
  };
}

// Check if already exists
const exists = whitelist.channels.some(ch => ch.name === target || ch.id === target);

if (exists) {
  return {
    json: {
      success: false,
      responseText: `Channel ${target} is already whitelisted.`,
      whitelist
    }
  };
}

// Add new channel
whitelist.channels.push({
  id: target,
  name: target,
  added_by: userId,
  added_at: timestamp
});

return {
  json: {
    success: true,
    whitelist,
    channelName: target
  }
};

// Remove channel from whitelist
const whitelist = $node['Verify Admin'].json.whitelistData;
const target = $node['Verify Admin'].json.commandData.target;

if (!target) {
  return {
    json: {
      success: false,
      responseText: 'Please specify a channel. Usage: /admin revoke #channel-name'
    }
  };
}

// Find and remove channel
const initialLength = whitelist.channels.length;
whitelist.channels = whitelist.channels.filter(ch => 
  ch.name !== target && ch.id !== target
);

const removed = whitelist.channels.length < initialLength;

if (!removed) {
  return {
    json: {
      success: false,
      responseText: `Channel ${target} was not found in whitelist.`,
      whitelist
    }
  };
}

return {
  json: {
    success: true,
    whitelist,
    channelName: target
  }
};

// List all channels and admins
const whitelist = $node['Verify Admin'].json.whitelistData;
const templates = JSON.parse($node['Load Templates'].json.data);

let responseText = templates.admin.list_header.replace('{{count}}', whitelist.channels.length) + '\n';

if (whitelist.channels.length === 0) {
  responseText += templates.admin.list_empty + '\n';
} else {
  whitelist.channels.forEach(ch => {
    const date = new Date(ch.added_at).toLocaleDateString();
    responseText += templates.admin.list_item
      .replace('{{channel_name}}', ch.name)
      .replace('{{admin_name}}', ch.added_by)
      .replace('{{date}}', date) + '\n';
  });
}

responseText += '\n' + templates.admin.admins_header.replace('{{count}}', whitelist.admins.length) + '\n';

whitelist.admins.forEach(admin => {
  responseText += templates.admin.admin_item
    .replace('{{admin_name}}', admin.name)
    .replace('{{admin_id}}', admin.id) + '\n';
});

return {
  json: {
    success: true,
    responseText,
    whitelist
  }
};

// Format success response
const templates = JSON.parse($node['Load Templates for Response'].json.data);
const success = $json.success;
const action = $node['Verify Admin'].json.commandData.action;
const channelName = $json.channelName || '';

let responseText = '';

if (action === 'list') {
  responseText = $json.responseText;
} else if (action === 'allow' && success) {
  responseText = templates.success.whitelist_added.replace('{{channel_name}}', channelName);
} else if (action === 'revoke' && success) {
  responseText = templates.success.whitelist_revoked.replace('{{channel_name}}', channelName);
} else {
  responseText = $json.responseText || 'Unknown error occurred.';
}

return {
  json: {
    responseText
  }
};
